/**
 * Action 06 Prompt Module for tx-11-imp-1 Agent
 * 
 * Responsibility: Generate prompt for Action 6 - メンバーの日報作成時に参考情報を提示
 * This action provides reference information to members when creating daily reports,
 * including past issues, similar cases, and best practices.
 */

export const ACTION_06_PROMPT_VERSION = "1.0.0";

export interface Action06PromptContext {
  memberId: string;
  memberName: string;
  reportDate: string;
  pastIssues: Array<{
    issueId: string;
    title: string;
    category: string;
    priority: string;
    resolutionDate?: string;
    description: string;
  }>;
  similarCases: Array<{
    caseId: string;
    title: string;
    category: string;
    resolution: string;
    reportedDate: string;
  }>;
  bestPractices: Array<{
    practiceId: string;
    title: string;
    description: string;
    category: string;
  }>;
  recentReportingPatterns: {
    commonIssueCategories: string[];
    frequentProblems: string[];
    averageIssuesPerReport: number;
  };
}

export interface Action06PromptOutput {
  referenceInformation: string;
  suggestedCategories: string[];
  relatedPastIssues: Array<{
    issueId: string;
    title: string;
    relevanceScore: number;
  }>;
  bestPracticesTips: string[];
  promptText: string;
}

export function buildAction06Prompt(context: Action06PromptContext): Action06PromptOutput {
  const referenceInformation = generateReferenceInformation(context);
  const suggestedCategories = extractSuggestedCategories(context);
  const relatedPastIssues = rankRelatedIssues(context);
  const bestPracticesTips = compileBestPracticesTips(context);
  const promptText = constructPromptText(
    context,
    referenceInformation,
    suggestedCategories,
    relatedPastIssues,
    bestPracticesTips
  );

  return {
    referenceInformation,
    suggestedCategories,
    relatedPastIssues,
    bestPracticesTips,
    promptText,
  };
}

function generateReferenceInformation(context: Action06PromptContext): string {
  const sections: string[] = [];

  sections.push(`=== 日報作成ガイド for ${context.memberName} ===`);
  sections.push(`作成日: ${context.reportDate}`);
  sections.push("");

  if (context.pastIssues.length > 0) {
    sections.push("【過去の報告課題】");
    const recentIssues = context.pastIssues.slice(0, 5);
    recentIssues.forEach((issue) => {
      sections.push(
        `- [${issue.priority}] ${issue.title} (${issue.category})`
      );
      if (issue.resolutionDate) {
        sections.push(`  解決日: ${issue.resolutionDate}`);
      }
    });
    sections.push("");
  }

  if (context.similarCases.length > 0) {
    sections.push("【類似事例】");
    const topCases = context.similarCases.slice(0, 3);
    topCases.forEach((caseItem) => {
      sections.push(`- ${caseItem.title}`);
      sections.push(`  対応: ${caseItem.resolution}`);
    });
    sections.push("");
  }

  if (context.recentReportingPatterns.commonIssueCategories.length > 0) {
    sections.push("【よく報告されるカテゴリ】");
    context.recentReportingPatterns.commonIssueCategories.forEach((cat) => {
      sections.push(`- ${cat}`);
    });
    sections.push("");
  }

  return sections.join("\n");
}

function extractSuggestedCategories(context: Action06PromptContext): string[] {
  const categoryFrequency = new Map<string, number>();

  context.pastIssues.forEach((issue) => {
    categoryFrequency.set(
      issue.category,
      (categoryFrequency.get(issue.category) || 0) + 1
    );
  });

  context.similarCases.forEach((caseItem) => {
    categoryFrequency.set(
      caseItem.category,
      (categoryFrequency.get(caseItem.category) || 0) + 1
    );
  });

  return Array.from(categoryFrequency.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([category]) => category);
}

function rankRelatedIssues(
  context: Action06PromptContext
): Array<{
  issueId: string;
  title: string;
  relevanceScore: number;
}> {
  return context.pastIssues
    .map((issue) => ({
      issueId: issue.issueId,
      title: issue.title,
      relevanceScore: calculateRelevanceScore(issue, context),
    }))
    .sort((a, b) => b.relevanceScore - a.relevanceScore)
    .slice(0, 5);
}

function calculateRelevanceScore(
  issue: Action06PromptContext["pastIssues"][0],
  context: Action06PromptContext
): number {
  let score = 0;

  if (
    context.recentReportingPatterns.commonIssueCategories.includes(
      issue.category
    )
  ) {
    score += 30;
  }

  if (issue.priority === "HIGH" || issue.priority === "CRITICAL") {
    score += 20;
  }

  if (!issue.resolutionDate) {
    score += 15;
  }

  return score;
}

function compileBestPracticesTips(context: Action06PromptContext): string[] {
  const tips: string[] = [];

  if (context.bestPractices.length > 0) {
    context.bestPractices.slice(0, 3).forEach((practice) => {
      tips.push(`${practice.title}: ${practice.description}`);
    });
  }

  if (context.recentReportingPatterns.averageIssuesPerReport > 0) {
    tips.push(
      `平均 ${context.recentReportingPatterns.averageIssuesPerReport} 件の課題が報告されています`
    );
  }

  if (context.recentReportingPatterns.frequentProblems.length > 0) {
    tips.push(
      `よく報告される問題: ${context.recentReportingPatterns.frequentProblems.slice(0, 2).join(", ")}`
    );
  }

  return tips;
}

function constructPromptText(
  context: Action06PromptContext,
  referenceInformation: string,
  suggestedCategories: string[],
  relatedPastIssues: Array<{
    issueId: string;
    title: string;
    relevanceScore: number;
  }>,
  bestPracticesTips: string[]
): string {
  const lines: string[] = [];

  lines.push("あなたは朝会報告管理システムのアシスタントです。");
  lines.push(
    `メンバー「${context.memberName}」が本日（${context.reportDate}）の日報を作成する際に、`
  );
  lines.push("参考情報と作成ガイダンスを提供してください。");
  lines.push("");

  lines.push("【参考情報】");
  lines.push(referenceInformation);
  lines.push("");

  lines.push("【推奨カテゴリ】");
  suggestedCategories.forEach((cat) => {
    lines.push(`- ${cat}`);
  });
  lines.push("");

  lines.push("【関連する過去課題】");
  relatedPastIssues.forEach((issue) => {
    lines.push(
      `- ${issue.title} (関連度: ${Math.round(issue.relevanceScore)}%)`
    );
  });
  lines.push("");

  lines.push("【ベストプラクティス】");
  bestPracticesTips.forEach((tip) => {
    lines.push(`- ${tip}`);
  });
  lines.push("");

  lines.push("メンバーが日報を作成する際に、上記の情報を参考にして、");
  lines.push("より詳細で正確な報告ができるようにサポートしてください。");
  lines.push("特に、過去に同じ課題が報告されている場合は、");
  lines.push("その解決方法や進捗状況を参考にするよう促してください。");

  return lines.join("\n");
}
